import csv
import io
import unittest
from exporter import export_rows

class ExportTests(unittest.TestCase):
    def _data_rows(self, text):
        parsed = list(csv.reader(io.StringIO(text)))
        return parsed[1:]  # drop header

    def test_header(self):
        self.assertTrue(export_rows([]).startswith("customer_id,region"))

    def test_absent_region_is_na(self):
        rows = [{"customer_id": "001"}]
        self.assertEqual(self._data_rows(export_rows(rows)), [["001", "NA"]])

    def test_none_region_is_na(self):
        rows = [{"customer_id": "001", "region": None}]
        self.assertEqual(self._data_rows(export_rows(rows)), [["001", "NA"]])

    def test_empty_region_stays_empty(self):
        rows = [{"customer_id": "001", "region": ""}]
        self.assertEqual(self._data_rows(export_rows(rows)), [["001", ""]])

    def test_non_missing_region_preserved(self):
        rows = [{"customer_id": "001", "region": "us-east-1"}]
        self.assertEqual(self._data_rows(export_rows(rows)), [["001", "us-east-1"]])

    def test_leading_zero_customer_id_preserved(self):
        rows = [{"customer_id": "007", "region": None}]
        self.assertEqual(self._data_rows(export_rows(rows)), [["007", "NA"]])

    def test_mixed_rows(self):
        rows = [
            {"customer_id": "abc", "region": "eu-west-1"},
            {"customer_id": "002"},
            {"customer_id": "003", "region": None},
            {"customer_id": "004", "region": ""},
        ]
        self.assertEqual(
            self._data_rows(export_rows(rows)),
            [["abc", "eu-west-1"], ["002", "NA"], ["003", "NA"], ["004", ""]],
        )

if __name__ == "__main__":
    unittest.main()

